package com.swiftroute.mapper;

import com.swiftroute.dto.request.CreateUrlRequest;
import com.swiftroute.dto.response.UrlResponse;
import com.swiftroute.entity.Url;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;


@Mapper(componentModel = "spring")
public interface UrlMapper {

    // Converts Entity to Response DTO
    UrlResponse toResponse(Url url);

    // Converts Request DTO to Entity (ignores fields generated by the system)
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "user", ignore = true)
    @Mapping(target = "shortCode", ignore = true)
    Url toEntity(CreateUrlRequest request);
}
